#include <queue>
#include <vector>
#include <list>

// Define a priority queue with a custom underlying container (e.g., std::list)
std::priority_queue<int, std::list<int>> custom_pq;

// Insert elements
custom_pq.push(10);
custom_pq.push(5);
custom_pq.push(20);

// Access the top element
int top_element = custom_pq.top();

// Remove the top element
custom_pq.pop();
